const switcher = document.querySelector('.language-switch');
const id = new URLSearchParams(location.search).get('id') || 'viejito-perro';
const project = projects[id] || projects['viejito-perro'];
const isCenvi = id === 'cenvi';
const isPunitaqui = id === 'punitaqui';
const isCencosud = id === 'cencosud';
const isHuerto = id === 'huerto';
const isSoundPractices = id === 'practicas-sonoras';
const isSpanishOnly = isCenvi || isPunitaqui || isCencosud || isHuerto || isSoundPractices;
document.body.classList.toggle('viejito-detail-page', id === 'viejito-perro');
document.body.classList.toggle('cenvi-detail-page', isCenvi);
document.body.classList.toggle('punitaqui-detail-page', isPunitaqui);
document.body.classList.toggle('cencosud-detail-page', isCencosud);
document.body.classList.toggle('huerto-detail-page', isHuerto);
document.body.classList.toggle('sound-practices-detail-page', isSoundPractices);

if (isSpanishOnly) {
  switcher.disabled = true;
  switcher.classList.add('is-static');
  switcher.setAttribute('aria-label', 'Contenido disponible actualmente en español');
  switcher.setAttribute('aria-disabled', 'true');
  switcher.title = 'Versión en inglés pendiente';
}

function setupProjectLightbox() {
  const imageSelector = [
    '#viejito-story figure img',
    '#punitaqui-content figure img',
    '#cencosud-content figure img',
    '#huerto-content figure img',
    '#sound-practices-content figure img'
  ].join(',');

  document.querySelectorAll('.cenvi-media-button').forEach((button) => button.classList.add('project-media-button'));
  document.querySelectorAll(imageSelector).forEach((image) => {
    if (image.closest('.project-media-button')) return;
    const formerLink = image.parentElement?.tagName === 'A' ? image.parentElement : null;
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'project-media-button';
    button.setAttribute('aria-label', `Ampliar imagen: ${image.alt}`);
    if (formerLink) formerLink.replaceWith(button);
    else image.replaceWith(button);
    button.append(image);
    const hint = document.createElement('span');
    hint.className = 'cenvi-media-hint';
    hint.setAttribute('aria-hidden', 'true');
    hint.textContent = 'Ampliar';
    button.append(hint);
  });

  const items = [...document.querySelectorAll('.project-media-button')];
  const lightbox = document.querySelector('#project-lightbox');
  if (!lightbox || !items.length) return;

  const enlargedImage = lightbox.querySelector('img');
  const caption = lightbox.querySelector('figcaption');
  const closeButton = lightbox.querySelector('.cenvi-lightbox-close');
  const counter = lightbox.querySelector('.project-lightbox-counter');
  const previousButton = lightbox.querySelector('.project-lightbox-prev');
  const nextButton = lightbox.querySelector('.project-lightbox-next');
  let sectionItems = [];
  let currentIndex = 0;

  const showItem = (item) => {
    const figure = item.closest('figure');
    const sourceImage = item.querySelector('img');
    enlargedImage.src = sourceImage.currentSrc || sourceImage.src;
    enlargedImage.alt = sourceImage.alt;
    caption.textContent = figure.querySelector('figcaption')?.textContent
      || figure.closest('section')?.querySelector('.paired-caption')?.textContent
      || '';
    counter.textContent = `${currentIndex + 1} / ${sectionItems.length}`;
  };

  const moveWithinSection = (offset) => {
    currentIndex = (currentIndex + offset + sectionItems.length) % sectionItems.length;
    showItem(sectionItems[currentIndex]);
  };

  items.forEach((item) => {
    item.addEventListener('click', () => {
      const section = item.closest('section');
      sectionItems = section ? [...section.querySelectorAll('.project-media-button')] : [item];
      currentIndex = sectionItems.indexOf(item);
      const hasSiblings = sectionItems.length > 1;
      counter.hidden = !hasSiblings;
      previousButton.hidden = !hasSiblings;
      nextButton.hidden = !hasSiblings;
      showItem(item);
      lightbox.showModal();
    });
  });

  closeButton.addEventListener('click', () => lightbox.close());
  previousButton.addEventListener('click', () => moveWithinSection(-1));
  nextButton.addEventListener('click', () => moveWithinSection(1));
  lightbox.addEventListener('click', (event) => {
    if (event.target === lightbox) lightbox.close();
  });
  lightbox.addEventListener('keydown', (event) => {
    if (sectionItems.length < 2) return;
    if (event.key === 'ArrowLeft') {
      event.preventDefault();
      moveWithinSection(-1);
    }
    if (event.key === 'ArrowRight') {
      event.preventDefault();
      moveWithinSection(1);
    }
  });
}

function setupHuertoTimelapse() {
  const viewer = document.querySelector('[data-huerto-timelapse]');
  if (!viewer) return;

  const frames = [
    ['assets/huerto/siembra-19-septiembre.jpg', '2026-09-19', '19 de septiembre', 'Siembra y primer registro estabilizado.', 'Dos bandejas de germinación recién sembradas.'],
    ['assets/huerto/crecimiento-20-septiembre.jpg', '2026-09-20', '20 de septiembre', 'Primer brote visible.', 'Bandejas con el primer brote verde apenas visible.'],
    ['assets/huerto/primeros-brotes-21-septiembre.jpg', '2026-09-21', '21 de septiembre', 'Los rabanitos son los primeros en emerger.', 'Bandejas con los primeros brotes de rabanito visibles.'],
    ['assets/huerto/crecimiento-22-septiembre.jpg', '2026-09-22', '22 de septiembre', 'Aparecen brotes de albahaca y tomate.', 'Bandejas con nuevos brotes de albahaca y tomate.'],
    ['assets/huerto/emergencia-especies-23-septiembre.jpg', '2026-09-23', '23 de septiembre · mañana', 'Se distinguen ritmos diferentes de emergencia.', 'Bandejas con brotes de distintos tamaños en varias cavidades.'],
    ['assets/huerto/crecimiento-23-septiembre-tarde.jpg', '2026-09-23', '23 de septiembre · tarde', 'Las sondas se incorporan al montaje.', 'Cultivo con cables y sondas durante la incorporación del nodo vegetal.'],
    ['assets/huerto/montaje-nodo-vegetal.jpg', '2026-09-23', '23 de septiembre · montaje', 'El nodo conecta sensores y cultivo.', 'Nodo vegetal en protoboard instalado junto a las bandejas.'],
    ['assets/huerto/sensores-y-cultivo-24-septiembre.jpg', '2026-09-24', '24 de septiembre', 'Todas las especies han emergido.', 'Bandejas con sensores y plántulas de las tres especies.'],
    ['assets/huerto/crecimiento-26-septiembre.jpg', '2026-09-26', '26 de septiembre', 'El crecimiento hace más visibles las diferencias.', 'Cultivo con plántulas de distintos tamaños seis días después de la primera emergencia.'],
    ['assets/huerto/crecimiento-27-septiembre.jpg', '2026-09-27', '27 de septiembre', 'Los rabanitos comienzan a desbordar sus cavidades.', 'Bandejas con rabanitos alargados y tomates en crecimiento.'],
    ['assets/huerto/crecimiento-28-septiembre.jpg', '2026-09-28', '28 de septiembre', 'La posición de algunas plantas altera la comparación.', 'Cultivo con tallos inclinados que cruzan los límites de las cavidades.'],
    ['assets/huerto/crecimiento-2-octubre.jpg', '2026-10-02', '2 de octubre', 'El crecimiento vuelve necesarias nuevas intervenciones.', 'Tomates, rabanitos y albahacas desarrollados dentro de las bandejas.']
  ];
  const image = viewer.querySelector('[data-timelapse-image]');
  const date = viewer.querySelector('[data-timelapse-date]');
  const note = viewer.querySelector('[data-timelapse-note]');
  const range = viewer.querySelector('[data-timelapse-range]');
  const counter = viewer.querySelector('[data-timelapse-counter]');
  const play = viewer.querySelector('[data-timelapse-play]');
  let timer = null;

  const showFrame = (index) => {
    const [src, datetime, label, description, alt] = frames[index];
    image.src = src;
    image.alt = alt;
    date.dateTime = datetime;
    date.textContent = label;
    note.textContent = ` · ${description}`;
    range.value = String(index);
    counter.textContent = `${index + 1} / ${frames.length}`;
  };
  const stop = () => {
    clearInterval(timer);
    timer = null;
    play.textContent = 'Reproducir secuencia';
    play.setAttribute('aria-pressed', 'false');
  };
  const start = () => {
    play.textContent = 'Pausar secuencia';
    play.setAttribute('aria-pressed', 'true');
    timer = setInterval(() => showFrame((Number(range.value) + 1) % frames.length), 950);
  };

  frames.slice(1).forEach(([src]) => { const preload = new Image(); preload.src = src; });
  range.addEventListener('input', () => { stop(); showFrame(Number(range.value)); });
  play.addEventListener('click', () => { if (timer) stop(); else start(); });
  document.addEventListener('visibilitychange', () => { if (document.hidden && timer) stop(); });
}

function render(language) {
  if (isSpanishOnly) language = 'es';
  const [title, status, intro, problem, process, role, credits, evidence] = project[language];
  document.documentElement.lang = language;
  document.querySelectorAll('[data-es][data-en]').forEach((element) => { element.textContent = element.dataset[language]; });
  document.querySelector('#project-title').textContent = title;
  document.querySelector('#project-status').textContent = status;
  document.querySelector('#project-intro').textContent = intro;
  document.querySelector('#project-problem').textContent = problem;
  document.querySelector('#project-process').textContent = process;
  document.querySelector('#project-role').textContent = role;
  document.querySelector('#project-credits').textContent = credits;
  const richStory = document.querySelector('#viejito-story');
  const showRichStory = id === 'viejito-perro' && language === 'es';
  richStory.hidden = !showRichStory;
  document.querySelector('#project-standard-content').hidden = showRichStory || isSpanishOnly;
  document.querySelector('#project-standard-evidence').hidden = showRichStory || isSpanishOnly;
  const list = document.querySelector('#project-evidence');
  list.replaceChildren(...evidence.map((item) => { const li = document.createElement('li'); li.textContent = item; return li; }));
  document.title = `${title} — Raúl Zuleta`;
  const english = language === 'en';
  switcher.setAttribute('aria-pressed', String(english));
  if (!isSpanishOnly) switcher.setAttribute('aria-label', english ? 'Cambiar idioma a español' : 'Change language to English');
  switcher.children[0].classList.toggle('active', !english);
  switcher.children[1].classList.toggle('active', english);
  localStorage.setItem('portfolio-language', language);
}

if (isCenvi) {
  document.querySelector('#project-standard-content').hidden = true;
  document.querySelector('#project-standard-evidence').hidden = true;
  document.querySelector('#cenvi-content').hidden = false;
} else if (isPunitaqui) {
  document.querySelector('#project-standard-content').hidden = true;
  document.querySelector('#project-standard-evidence').hidden = true;
  document.querySelector('#punitaqui-content').hidden = false;
} else if (isCencosud) {
  document.querySelector('#project-standard-content').hidden = true;
  document.querySelector('#project-standard-evidence').hidden = true;
  document.querySelector('#cencosud-content').hidden = false;
} else if (isHuerto) {
  document.querySelector('#project-standard-content').hidden = true;
  document.querySelector('#project-standard-evidence').hidden = true;
  document.querySelector('#huerto-content').hidden = false;
} else if (isSoundPractices) {
  document.querySelector('#project-standard-content').hidden = true;
  document.querySelector('#project-standard-evidence').hidden = true;
  document.querySelector('#sound-practices-content').hidden = false;
} else {
  switcher.addEventListener('click', () => render(document.documentElement.lang === 'es' ? 'en' : 'es'));
}
setupHuertoTimelapse();
setupProjectLightbox();
render(isSpanishOnly ? 'es' : (localStorage.getItem('portfolio-language') === 'en' ? 'en' : 'es'));
